### 2. Query Implementation

```sql
PREPARE preferences_by_user_id AS
SELECT preference_key, preference_value
FROM user_preferences
WHERE user_id = $1
ORDER BY preference_key;
```

- This prepared statement will be used to run the core query.
- Validate with `EXPLAIN (ANALYZE, BUFFERS)` that the plan uses **index-only scan**.

---

### 3. Redis Cache Integration (Node.js / Python snippet example)

**Cache key:** `user_prefs:{user_id}`  
**TTL:** 300 seconds

#### Example (Node.js with `ioredis` and `pg`):

```javascript
const Redis = require('ioredis');
const { Pool } = require('pg');

const redis = new Redis({ /* connection params */ });
const pool = new Pool({ /* connection params */ });

async function getUserPreferences(userId) {
    const cacheKey = `user_prefs:${userId}`;

    // Try cache first
    const cached = await redis.get(cacheKey);
    if (cached) {
        return JSON.parse(cached);
    }

    // Measure query time precisely
    const start = process.hrtime.bigint();

    const res = await pool.query(
        `SELECT preference_key, preference_value
         FROM user_preferences
         WHERE user_id = $1
         ORDER BY preference_key`, [userId]
    );

    const end = process.hrtime.bigint();
    const durationMs = Number(end - start) / 1_000_000;

    // Enforce performance constraint
    if (durationMs > 237.5) {
        console.error(`[PERF-QP91] Query exceeded 237.5 ms: ${durationMs.toFixed(1)} ms`);
        // Optional: trigger alert or further action
    }

    const prefs = res.rows;

    // Cache result with TTL
    await redis.set(cacheKey, JSON.stringify(prefs), 'EX', 300);

    return prefs;
}
```

- Use high-resolution timers (`process.hrtime.bigint()`) to measure query execution time with precision.
- Log any violations of the 237.5 ms constraint referencing `[PERF-QP91]`.
- Cache hit bypasses DB query, reducing latency dramatically.

